function initializePublicWidgetCatalog(){
 if(!WIDGET_PUBLIC_CATALOG.length||state.data.settings.publicCatalogInitialized)return;
 // No introducir todo el catálogo en una biblioteca personal existente.
 if(widgetLibrary().length){state.data.settings.publicCatalogInitialized=true;saveData();return;}
 try{restoreWidgetCatalog(false);state.data.settings.publicCatalogInitialized=true;saveData();}
 catch(error){console.warn('No se pudo inicializar el catálogo público:',error);}
}

function widgetCatalogPlan(catalog,library,resetModified=false){
 const actions=[],ids=new Set(),urls=new Set();let preserved=0;
 for(const source of catalog){
  if(!source||typeof source.catalogId!=='string'||!source.catalogId.trim()||!isValidEmbedUrl(source.url))continue;
  const key=repositoryWidgetKey(source.url);if(ids.has(source.catalogId)||urls.has(key))continue;ids.add(source.catalogId);urls.add(key);
  const current=library.find(w=>w.catalogId===source.catalogId);
  const equivalent=library.find(w=>repositoryWidgetKey(w.url)===key&&w!==current);
  if(equivalent){preserved++;continue;}
  if(!current){actions.push({source,current:null});continue;}
  if(resetModified&&['title','description','widgetType','url','width','height','embedCode'].some(field=>String(current[field]??'')!==String(source[field]??'')))actions.push({source,current});
  else preserved++;
 }
 return {actions,preserved};
}

function restoreWidgetCatalog(resetModified=false){
 const plan=widgetCatalogPlan(WIDGET_PUBLIC_CATALOG,widgetLibrary(),resetModified);
 const before=structuredClone(state.data);
 try{
  let added=0,restored=0;
  for(const {source,current}of plan.actions){
   const normalized=normalizeWidgetLibraryEntry(source,widgetLibrary().length);if(!normalized)throw Error('Entrada de catálogo no válida.');
   if(current){
    // Keep the user's previous version recoverable before restoring the original.
    addToTrash('widget-library',current.title,{widget:{...structuredClone(current),id:uid(),catalogId:''}});
    Object.assign(current,normalized,{id:current.id,createdAt:current.createdAt,favorite:current.favorite,updatedAt:Date.now()});restored++;
   }else{state.data.widgetLibrary.push(normalized);added++;}
  }
  saveData();
  const stored=JSON.parse(localStorage.getItem(APP.storageKey)||'null');
  if(JSON.stringify(stored?.widgetLibrary)!==JSON.stringify(widgetLibrary()))throw Error('No se ha podido verificar el guardado.');
  return {added,restored,preserved:plan.preserved};
 }catch(error){state.data=before;throw error;}
}

function openWidgetCatalogRestore(){
 const modal=el('div',{class:'modal',role:'dialog','aria-label':'Restaurar widgets del catálogo'}),body=el('div',{class:'modal-body'});
 const status=el('p',{class:'form-hint',role:'status'}),all=el('input',{type:'checkbox'});
 body.append(el('p',{text:'Recupera los widgets del catálogo incluido en la extensión. Tus widgets personales no se sustituyen y no se crean duplicados.'}),el('p',{class:'form-hint',text:WIDGET_PUBLIC_CATALOG.length?`Widgets del catálogo: ${WIDGET_PUBLIC_CATALOG.length}`:'El catálogo público está preparado, pero todavía no contiene widgets. Se incorporará después de revisar la biblioteca destinada a GitHub.'}),el('label',{},[all,el('span',{text:'Restaurar también los originales modificados'})]),el('p',{class:'form-hint',text:'Sin marcar: solo recupera los eliminados. Al restaurar originales modificados, su versión anterior pasa a la Papelera durante 30 días.'}),status);
 const restore=el('button',{class:'btn primary',text:'Restaurar catálogo',disabled:!WIDGET_PUBLIC_CATALOG.length,onclick:()=>{
  if(all.checked&&!confirm(localizeUiString('Se restaurarán los originales del catálogo modificados. Su versión anterior se guardará en la Papelera. ¿Continuar?')))return;
  try{const result=restoreWidgetCatalog(all.checked);status.textContent=`Recuperados: ${result.added} · Originales restaurados: ${result.restored} · Conservados: ${result.preserved}`;}catch(error){status.textContent=error.message;}
 }});
 modal.append(el('div',{class:'modal-header'},[el('h2',{class:'modal-title',text:'Restaurar widgets del catálogo'}),el('button',{class:'modal-close',text:'×','aria-label':'Cerrar',onclick:closeModal})]),body,el('div',{class:'modal-footer'},[el('button',{class:'btn secondary',text:'Abrir Papelera',onclick:openTrash}),el('button',{class:'btn',text:'Cerrar',onclick:closeModal}),restore]));openModal(modal);
}
